namespace Inventory;

/// <summary>Allocates available stock across a warehouse's zones.</summary>
public sealed class AllocationCalculator
{
    public IReadOnlyList<string> Allocate(StockItem item, Warehouse warehouse)
    {
        var result = new List<string>();
        int remaining = item.OnHand - item.Reserved;
        if (remaining <= 0)
            return result;

        foreach (var zone in warehouse.Zones)
        {
            if (TryAllocateToZone(zone, result, ref remaining) && remaining <= 0)
                break;
        }

        if (remaining > 0)
            result.Add($"OVERFLOW:{remaining}");
        return result;
    }

    private static bool TryAllocateToZone(
        Zone zone,
        List<string> result,
        ref int remaining)
    {
        if (zone.Capacity <= 0)
            return false;
        if (string.IsNullOrEmpty(zone.Name))
            return false;

        int place = CalculatePlacement(zone, remaining);
        if (place <= 0)
            return false;

        result.Add($"{zone.Name}:{place}");
        remaining -= place;
        return true;
    }

    private static int CalculatePlacement(Zone zone, int remaining)
    {
        if (remaining > zone.Capacity)
            return zone.Capacity;
        if (remaining > zone.Capacity / 2)
            return remaining - 1;
        return remaining;
    }
}
